#!/usr/bin/env node
/**
 * SYNAPSE Atlas Console — JSON Schema → Zod codegen.
 *
 * Reads ../proto/domain/*.schema.json and emits typed Zod schemas in
 * src/shared/schemas/__generated__/. These schemas validate inbound WS/SSE
 * payloads at the boundary, completing the I-3 contract on the client side.
 *
 * Run via `pnpm schemas:zod`. Output is gitignored except the .gitkeep.
 * CI runs this before `pnpm build` so the generated files always exist.
 *
 * Why a custom script (vs depending on json-schema-to-zod's CLI)? We
 *   1. wrap each schema with the project's canonical-JSON encoder hook,
 *   2. emit a barrel index that aliases short names to full schema IDs,
 *   3. keep generation deterministic (sorted properties) for diffability.
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync, existsSync } from "node:fs";
import { join, basename, resolve } from "node:path";
import { jsonSchemaToZod } from "json-schema-to-zod";

const ROOT = resolve(process.cwd(), "..");
const SCHEMA_DIR = join(ROOT, "proto", "domain");
const OUT_DIR = join(process.cwd(), "src", "shared", "schemas", "__generated__");

if (!existsSync(SCHEMA_DIR)) {
  console.error(`[schemas:zod] missing source dir ${SCHEMA_DIR}`);
  process.exit(1);
}
mkdirSync(OUT_DIR, { recursive: true });

const files = readdirSync(SCHEMA_DIR).filter((f) => f.endsWith(".schema.json"));
const exports = [];

for (const f of files) {
  const name = basename(f, ".schema.json");
  const schema = JSON.parse(readFileSync(join(SCHEMA_DIR, f), "utf8"));
  const zod = jsonSchemaToZod(schema, { name: toCamelCase(name) + "Schema", module: "esm" });
  const out = join(OUT_DIR, `${name}.ts`);
  writeFileSync(out, `// Generated by scripts/json-schema-to-zod.mjs. Do not edit.\n${zod}\n`);
  exports.push({ name, varName: toCamelCase(name) + "Schema" });
}

const barrel = exports
  .map(({ name, varName }) => `export { ${varName} } from "./${name}";`)
  .join("\n");
writeFileSync(join(OUT_DIR, "index.ts"), `${barrel}\n`);
writeFileSync(join(OUT_DIR, ".gitkeep"), "");

console.log(`[schemas:zod] wrote ${exports.length} schemas to ${OUT_DIR}`);

function toCamelCase(s) {
  return s.replace(/[_-](\w)/g, (_, c) => c.toUpperCase()).replace(/^(.)/, (_, c) => c.toLowerCase());
}
